// #1ccd9e / #55dc54 — тендеры компании: USER видит тендеры компании A, ADMIN видит тендер USER,
// компания B (admin2) не видит тендеры A ни в ленте, ни по прямому адресу.
// Кейсы: .qa/tests/permissions-isolation/PI-04, PI-07, PI-08. Только просмотр, данных не создаётся.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { ALL_TENDERS_A, TENDERS_A, TENDER_NOT_IN_ACCOUNT, tenderUrl } from './test-data';

const FEED_TABS = ['מכרזים מותאמים לי', 'מכרזים נוספים בתחומי הפעילות'];

/** id тендеров в ленте «/» по обеим вкладкам (ссылки «לפרטים» → /tenders/<id>/analysis). */
async function feedTenderIds(page: Page): Promise<Set<string>> {
  await page.goto('/');
  await expect(page.getByLabel('סיכום מכרזים')).toBeVisible(); // лента загружена
  const ids = new Set<string>();
  for (const tab of FEED_TABS) {
    const button = page.getByRole('group', { name: 'תצוגת פיד' }).getByRole('button', { name: tab, exact: true });
    await button.click();
    await expect(button).toHaveAttribute('aria-pressed', 'true');
    const hrefs = await page.getByRole('link', { name: 'לפרטים', exact: true }).evaluateAll((els) =>
      els.map((a) => a.getAttribute('href') ?? ''),
    );
    for (const h of hrefs) {
      const id = h.match(/^\/tenders\/([^/]+)\/analysis$/)?.[1];
      if (id) ids.add(id);
    }
  }
  return ids;
}

/** Тендер открылся: есть карточка с «מועד הגשה», нет «המכרז אינו זמין». */
async function expectTenderOpens(page: Page, id: string) {
  await page.goto(tenderUrl(id));
  await expect(page.getByText('מועד הגשה', { exact: true })).toBeVisible();
  await expect(page.getByRole('heading', { name: 'המכרז אינו זמין' })).toHaveCount(0);
}

test.describe('מכרזי החברה — משתמשים באותה חברה', () => {
  test('משתמש רגיל רואה את מכרזי החברה בפיד ופותח אותם #1ccd9e #55dc54 @desktop @prod-safe', async ({ asUser }) => {
    const user = await asUser('user');
    const ids = await feedTenderIds(user);
    for (const id of ALL_TENDERS_A) expect(ids, `тендер ${id} компании A в ленте USER`).toContain(id);
    await expectTenderOpens(user, TENDERS_A.byAdmin1);
    await expectTenderOpens(user, TENDERS_A.byAdmin2);
  });

  test('מנהל חשבון רואה מכרז שיצר משתמש רגיל #1ccd9e #55dc54 @desktop @prod-safe', async ({ asUser }) => {
    const admin = await asUser('admin');
    const ids = await feedTenderIds(admin);
    expect(ids, 'тендер USER в ленте ADMIN').toContain(TENDERS_A.byUser);
    await expectTenderOpens(admin, TENDERS_A.byUser);
  });
});

test.describe('הפרדת נתונים — חברה B לא רואה מכרזי חברה A', () => {
  test('מנהל חברה B לא רואה מכרזי חברה A בפיד #55dc54 @desktop @prod-safe', async ({ asUser }) => {
    const admin2 = await asUser('admin2');
    const ids = await feedTenderIds(admin2);
    for (const id of ALL_TENDERS_A) expect(ids, `тендер ${id} компании A в ленте компании B`).not.toContain(id);
  });

  for (const [label, id] of Object.entries(TENDERS_A)) {
    test(`כתובת ישירה למכרז חברה A (${label}) → "המכרז לא נמצא בחשבון שלך" #55dc54 @desktop @prod-safe`, async ({ asUser }) => {
      const admin2 = await asUser('admin2');
      await admin2.goto(tenderUrl(id));
      await expect(admin2.getByRole('heading', { name: 'המכרז אינו זמין' })).toBeVisible();
      await expect(admin2.getByText(TENDER_NOT_IN_ACCOUNT, { exact: true })).toBeVisible();
      await expect(admin2.getByText('מועד הגשה', { exact: true })).toHaveCount(0);
    });
  }
});
